def generated_loss(batch, model_output, extra):
    alpha = float(extra.get("alpha", 1.0))
    log_prob_w = batch["log_prob_w"]
    log_prob_l = batch["log_prob_l"]
    cost_gap = batch.get("cost_gap")
    if cost_gap is None:
        cost_gap = zeros_like(log_prob_w)
    scaled_gap = -alpha * cost_gap
    loss_values = logsigmoid(scaled_gap)
    return -mean(loss_values)

